import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaMapMarkerAlt,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaFileAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
  FaCheckCircle,
  FaTimesCircle,
  FaRedo,
} from "react-icons/fa";

import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";
const CLEAR_IMAGE_URL =
  "https://iranaserviceapp.ir/test/files/clear";

const PERSIAN_DIGITS = "۰۱۲۳۴۵۶۷۸۹";

// =====================================================
// تبدیل اعداد انگلیسی به فارسی
// =====================================================

function toPersianDigits(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  return String(value).replace(
    /\d/g,
    (digit) =>
      PERSIAN_DIGITS[Number(digit)]
  );
}

// =====================================================
// فرمت تاریخ
// =====================================================

function formatDate(dateString) {
  if (!dateString) {
    return "—";
  }

  const parts = String(dateString).split("/");

  if (parts.length !== 3) {
    return dateString;
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  // اگر تاریخ از قبل شمسی باشد
  if (year < 1700) {
    return `${toPersianDigits(year)}/${toPersianDigits(
      String(month).padStart(2, "0")
    )}/${toPersianDigits(
      String(day).padStart(2, "0")
    )}`;
  }

  try {
    const date = new Date(
      year,
      month - 1,
      day
    );

    return new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }
    ).format(date);
  } catch (error) {
    console.error(
      "DATE FORMAT ERROR:",
      error
    );

    return dateString;
  }
}

// =====================================================
// تشخیص وضعیت درخواست
// =====================================================

function getRequestStatus(request, clear) {
  /*
   * اگر clear وجود داشته باشد یعنی درخواست
   * تسویه شده است.
   */

  if (
    clear !== null &&
    clear !== undefined
  ) {
    return {
      type: "settled",
      text: "تسویه شده",
      className:
        "text-success fw-semibold",
      icon: <FaCheckCircle />,
    };
  }

  /*
   * در API فعلی، برای کنسل و مجدد فعال‌سازی
   * فیلدهای status / end / cleared یکسان هستند.
   *
   * بنابراین فعلاً از end_description
   * برای تشخیص استفاده می‌کنیم.
   */

  const description =
    String(
      request.end_description || ""
    ).trim();

  const normalized =
    description.toLowerCase();

  // ==========================================
  // مواردی که نشان‌دهنده کنسلی هستند
  // ==========================================

  const cancelKeywords = [
    "هزینه زیاد",
    "انصراف",
    "کنسل",
    "لغو",
    "نخواست",
    "عدم تمایل",
    "هزینه",
  ];

  const isCanceled =
    cancelKeywords.some(
      (keyword) =>
        normalized.includes(keyword)
    );

  if (isCanceled) {
    return {
      type: "canceled",
      text: "کنسل شده توسط تعمیرکار",
      className:
        "text-danger fw-semibold",
      icon: <FaTimesCircle />,
    };
  }

  // ==========================================
  // مواردی که نشان‌دهنده فعال‌سازی مجدد هستند
  // ==========================================

  const reactivatedKeywords = [
    "مجدد",
    "فعال",
    "فعال سازی",
    "فعال‌سازی",
    "دوباره",
    "درست شده",
    "درست بود",
    "رفع شده",
  ];

  const isReactivated =
    reactivatedKeywords.some(
      (keyword) =>
        normalized.includes(keyword)
    );

  if (isReactivated) {
    return {
      type: "reactivated",
      text: "مجدد فعال‌سازی شده",
      className:
        "text-primary fw-semibold",
      icon: <FaRedo />,
    };
  }

  // ==========================================
  // اگر وضعیت قابل تشخیص نبود
  // ==========================================

  return {
    type: "unknown",
    text: "وضعیت نامشخص",
    className:
      "text-muted fw-semibold",
    icon: <FaExclamationCircle />,
  };
}

// =====================================================
// کامپوننت
// =====================================================

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
      error: "",
    };

    this.handleBack =
      this.handleBack.bind(this);

    this.handleChat =
      this.handleChat.bind(this);

    this.handleAddRelated =
      this.handleAddRelated.bind(this);
  }

  // =====================================================
  // شروع صفحه
  // =====================================================

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  // =====================================================
  // دریافت جزئیات درخواست
  // =====================================================

  getRequestDetail = async () => {
    const { id } =
      this.props.params;

    const token =
      localStorage.getItem("token");

    console.log(
      "REQUEST ID:",
      id
    );

    if (!id) {
      this.setState({
        loading: false,
        error:
          "شناسه درخواست پیدا نشد.",
      });

      return;
    }

    if (!token) {
      this.setState({
        loading: false,
        error:
          "توکن ورود پیدا نشد.",
      });

      return;
    }

    const url =
      `${API_URL}/detail?id=${encodeURIComponent(
        id
      )}`;

    console.log(
      "REQUEST DETAIL URL:",
      url
    );

    try {
      const response =
        await fetch(url, {
          method: "GET",

          headers: {
            Accept:
              "application/json",
            Authorization:
              `Bearer ${token}`,
          },
        });

      console.log(
        "HTTP STATUS:",
        response.status
      );

      if (!response.ok) {
        throw new Error(
          `HTTP ${response.status}`
        );
      }

      const data =
        await response.json();

      console.log(
        "REQUEST DETAIL API:",
        data
      );

      if (
        String(data.status) !==
        "1"
      ) {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error:
            data.message ||
            "اطلاعات درخواست پیدا نشد.",
        });

        return;
      }

      const request =
        data.request || null;

      const clear =
        data.clear || null;

      if (!request) {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error:
            "درخواست پیدا نشد.",
        });

        return;
      }

      this.setState({
        request,
        clear,
        loading: false,
        error: "",
      });
    } catch (error) {
      console.error(
        "GET REQUEST DETAIL ERROR:",
        error
      );

      this.setState({
        request: null,
        clear: null,
        loading: false,
        error:
          "خطا در دریافت اطلاعات درخواست.",
      });
    }
  };

  // =====================================================
  // بازگشت
  // =====================================================

  handleBack() {
    this.props.navigate(-1);
  }

  // =====================================================
  // گفتگو
  // =====================================================

  handleChat() {
    console.log(
      "رفتن به گفتگو"
    );
  }

  // =====================================================
  // درخواست مرتبط
  // =====================================================

  handleAddRelated() {
    console.log(
      "افزودن درخواست مرتبط"
    );
  }

  // =====================================================
  // Render
  // =====================================================

  render() {
    const {
      authenticated,
      request,
      clear,
      loading,
      error,
    } = this.state;

    // =================================================
    // احراز هویت
    // =================================================

    if (!authenticated) {
      return null;
    }

    // =================================================
    // Loader
    // =================================================

    if (loading) {
      return <Loader />;
    }

    // =================================================
    // Error
    // =================================================

    if (error) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-danger">
            {error}
          </div>
        </div>
      );
    }

    // =================================================
    // درخواست وجود ندارد
    // =================================================

    if (!request) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            درخواست پیدا نشد.
          </div>
        </div>
      );
    }

    // =================================================
    // تعمیرکار
    // =================================================

    const technician =
      request.repairman_model;

    const technicianName =
      technician
        ? `${technician.name || ""} ${
            technician.family || ""
          }`.trim()
        : "—";

    // =================================================
    // وضعیت درخواست
    // =================================================

    const requestStatus =
      getRequestStatus(
        request,
        clear
      );

    // =================================================
    // اطلاعات مالی
    // =================================================

    const totalReceived =
      Number(request.sum || 0);

    const suppliesCost =
      Number(request.abzar || 0);

    const totalFee =
      totalReceived -
      suppliesCost;

    const commissionPercent =
      Number(
        request.porsant || 0
      );

    const commissionAmount =
      totalFee > 0 &&
      commissionPercent > 0
        ? (totalFee *
            commissionPercent) /
          100
        : 0;

    // =================================================
    // فیش واریزی
    // =================================================

    const receiptImage =
      request.file1 &&
      request.file1 !== ""
        ? `${CLEAR_IMAGE_URL}/${request.file1}`
        : null;

    // =================================================
    // درخواست‌های مرتبط
    // =================================================

    const relatedRequests =
      Array.isArray(
        request.siblings
      )
        ? request.siblings
        : [];

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* ==========================================
              هدر
          ========================================== */}

          <div className="d-flex align-items-center justify-content-between mb-4">

            {/* بازگشت */}

            <button
              type="button"
              onClick={
                this.handleBack
              }
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft
                size={14}
              />
            </button>

            {/* گفتگو */}

            <button
              type="button"
              onClick={
                this.handleChat
              }
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center text-danger"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaCommentDots
                size={16}
              />
            </button>

          </div>

          {/* ==========================================
              اطلاعات درخواست
          ========================================== */}

          <InfoField
            icon={
              <FaClone size={18} />
            }
            label="شماره درخواست"
            value={
              request.code || "—"
            }
          />

          <InfoField
            icon={
              <FaUserCog size={18} />
            }
            label="نام تعمیرکار"
            value={
              technicianName
            }
          />

          <InfoField
            icon={
              <FaUserEdit size={18} />
            }
            label="نام مشتری"
            value={
              request.name || "—"
            }
          />

          <InfoField
            icon={
              <FaPhoneAlt
                size={18}
              />
            }
            label="شماره تماس"
            value={
              request.mobile ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaPhone
                size={18}
              />
            }
            label="تلفن ثابت"
            value={
              request.mobile2 ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaMapMarkerAlt
                size={18}
              />
            }
            label="استان"
            value={
              request
                .state_model
                ?.name || "—"
            }
          />

          <InfoField
            icon={
              <FaMapMarkerAlt
                size={18}
              />
            }
            label="آدرس"
            value={
              request.address ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaMicrochip
                size={18}
              />
            }
            label="نوع دستگاه"
            value={
              request.device_type ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaTag size={18} />
            }
            label="برند دستگاه"
            value={
              request.device_brand ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaQuestionCircle
                size={18}
              />
            }
            label="ایراد دستگاه"
            value={
              request.problem ||
              "—"
            }
          />

          <InfoField
            icon={
              <FaClock
                size={18}
              />
            }
            label="زمان مراجعه"
            value={
              formatDate(
                request.time
              )
            }
          />

          <InfoField
            icon={
              <FaSyncAlt
                size={18}
              />
            }
            label="توضیحات"
            value={
              request.description ||
              "—"
            }
          />

          {/* ==========================================
              وضعیت
          ========================================== */}

          <InfoField
            icon={
              requestStatus.icon
            }
            label="وضعیت"
          >
            <span
              className={
                requestStatus.className
              }
            >
              {requestStatus.text}
            </span>
          </InfoField>

          {/* ==========================================
              توضیحات پایان درخواست
          ========================================== */}

          {request.end_description && (
            <InfoField
              icon={
                <FaExclamationCircle
                  size={18}
                />
              }
              label="توضیحات وضعیت"
              value={
                request.end_description
              }
            />
          )}

          {/* ==========================================
              اطلاعات مالی
              فقط در صورت وجود clear
          ========================================== */}

          {clear && (
            <>
              <InfoField
                icon={
                  <FaCoins
                    size={18}
                  />
                }
                label="کل دریافتی"
              >
                <span className="fw-semibold">
                  {totalReceived.toLocaleString(
                    "fa-IR"
                  )}{" "}
                  تومان
                </span>
              </InfoField>

              <InfoField
                icon={
                  <FaCoins
                    size={18}
                  />
                }
                label="هزینه لوازم مصرفی"
              >
                <span className="fw-semibold">
                  {suppliesCost.toLocaleString(
                    "fa-IR"
                  )}{" "}
                  تومان
                </span>
              </InfoField>

              <InfoField
                icon={
                  <FaBoxOpen
                    size={18}
                  />
                }
                label="لوازم مصرفی"
                value={
                  request.abzar_details ||
                  "—"
                }
              />

              <InfoField
                icon={
                  <FaFileInvoice
                    size={18}
                  />
                }
                label="کل اجرت"
              >
                <span className="fw-semibold">
                  {totalFee.toLocaleString(
                    "fa-IR"
                  )}{" "}
                  تومان
                </span>
              </InfoField>

              <InfoField
                icon={
                  <FaFileInvoice size={18} />
                }
                label={`پورسانت (%${commissionPercent})`}
              >
                <span className="fw-semibold">
                  {commissionAmount.toLocaleString(
                    "fa-IR"
                  )}{" "}
                  تومان
                </span>
              </InfoField>

              {/* فیش */}

              {receiptImage && (
                <div className="d-flex align-items-center justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">

                  <span className="text-muted">
                    فیش واریزی:
                  </span>

                  <img
                    src={
                      receiptImage
                    }
                    alt="فیش واریزی"
                    className="rounded-3 border"
                    style={{
                      width: 140,
                      height: 110,
                      objectFit:
                        "cover",
                      cursor:
                        "pointer",
                    }}
                  />

                </div>
              )}

              <InfoField
                icon={
                  <FaExclamationCircle
                    size={18}
                  />
                }
                label="توضیحات تایید تسویه"
                value={
                  clear.description ||
                  clear.desc ||
                  "—"
                }
              />
            </>
          )}

          {/* ==========================================
              درخواست‌های مرتبط
          ========================================== */}

          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            درخواست‌های مرتبط:
          </h2>

          {relatedRequests.length ===
          0 ? (
            <div className="text-center text-muted py-4">
              هنوز موردی برای نمایش وجود ندارد.
            </div>
          ) : (
            <div>
              {relatedRequests.map(
                (related) => (
                  <Link
                    key={
                      related.id
                    }
                    to={`/request-details/${related.id}`}
                    className="text-decoration-none text-dark"
                  >
                    <div className="border rounded-3 p-3 mb-2 text-end">
                      {related.code ||
                        related.id}
                    </div>
                  </Link>
                )
              )}
            </div>
          )}

          {/* ==========================================
              افزودن درخواست مرتبط
          ========================================== */}

          <button
            type="button"
            onClick={
              this.handleAddRelated
            }
            className="btn btn-primary w-100 rounded-3 py-3 mt-2"
          >
            افزودن درخواست مرتبط
          </button>

        </div>
      </div>
    );
  }
}

export default withRouter(
  RequestDetailPage
);
